export function logoSvg(height = COMPANY.logoHeight) {
  const cadre = Math.round(height * 1.415);
  const image = Math.round(height * 2.163);
  return `<span class="ct-logo" style="display:block;position:relative;width:${cadre}px;height:${height}px;overflow:hidden;margin:0 auto 2px">
      <img src="${COMPANY.logo}" alt="${COMPANY.logoWord}" style="position:absolute;left:50%;top:47.5%;width:${image}px;height:${image}px;transform:translate(-50%,-50%);max-width:none;display:block">
    </span>`;
}
